<script setup lang="ts">
import {onMounted,onUnmounted,ref,watch} from 'vue';
import {vModal} from './modal';
import CloudHistorySummary from './CloudHistorySummary.vue';
import CloudHistoryExport from './CloudHistoryExport.vue';
import {parseHistoryEvents,historyEventsURL,historySources,historyStatuses,historyPhases,historyTimeText,type HistorySource,type HistoryEvent,type HistoryRun} from './cloud-history-types';
const props=defineProps<{source:HistorySource;run:string;before:string;summary:{record:HistoryRun;observedAt:string}|null;disabled:boolean;previousLabel:string}>(),emit=defineEmits<{authenticationRequired:[];close:[];next:[string];previous:[]}>();
const rows=ref<HistoryEvent[]>([]),loading=ref(false),error=ref(''),observed=ref(''),next=ref('0'),more=ref(false);let active=true,generation=0,controller:AbortController|undefined;
const missing='历史未记录',kindLabels:Record<string,string>={started:'开始',resumed:'恢复',paused:'暂停',completed:'完成',failed:'失败',retry_scheduled:'计划重试',boundary_restart:'分页重核',request_budget_reached:'达到工具上限'};
function close(){emit('close');}
function stop(){active=false;generation++;controller?.abort();loading.value=false;}
async function load(){
 if(!active||props.disabled||loading.value)return;const request=++generation,source=props.source,run=props.run,before=props.before;controller=new AbortController();loading.value=true;
 try{const response=await fetch(historyEventsURL(source,run,before),{credentials:'same-origin',signal:controller.signal});if(request!==generation)return;if(response.status===401){stop();emit('authenticationRequired');return;}if(!response.ok)throw Error(response.status===404?'未找到该运行记录。':await response.text()||'事件暂不可读');const data=await response.json();if(request!==generation)return;const page=parseHistoryEvents(data,source,run,before);rows.value=page.rows;next.value=page.next;more.value=page.more;error.value='';observed.value=new Date().toISOString();}
 catch(e:any){if(request===generation)error.value=e.message||'事件暂不可读';}finally{if(request===generation)loading.value=false;}
}
function forceLoad(){generation++;controller?.abort();loading.value=false;load();}
function restore(event:PageTransitionEvent){if(event.persisted&&!props.disabled){active=true;load();}}
watch(()=>props.before,forceLoad);watch(()=>props.disabled,value=>{if(value)stop();});onMounted(()=>{window.addEventListener('pagehide',stop);window.addEventListener('pageshow',restore);load();});onUnmounted(()=>{stop();window.removeEventListener('pagehide',stop);window.removeEventListener('pageshow',restore);});
</script>
<template><div class="modal-backdrop" @click.self="close"><section class="detail-drawer history-detail-drawer" role="dialog" aria-modal="true" aria-labelledby="history-detail-title" data-testid="history-event-panel" v-modal="close"><header class="page-header"><div><h2 id="history-detail-title">{{historySources[source]}} · 运行详情</h2><p class="muted">固定运行 ID：{{run}}</p></div><button class="button secondary" @click="close">关闭</button></header><CloudHistorySummary v-if="summary&&summary.record.run_id===run&&summary.record.source===source" :record="summary.record" :observed-at="summary.observedAt"/><p v-else class="notice">本页没有此运行的摘要，事件仍按固定 ID 读取；不会借用其他运行的覆盖信息。</p><CloudHistoryExport :source="source" :run="run" :disabled="disabled" @authentication-required="emit('authenticationRequired')"/><header class="page-header"><h3>本轮关键事件</h3><button class="button secondary" :disabled="disabled||loading" @click="load">刷新事件</button></header><p v-if="loading" role="status">正在读取本地事件…</p><p v-if="error" role="alert" class="notice danger">{{error}}<span v-if="observed"> · 保留上次读取的本轮事件。</span></p><div class="event-table-scroll"><table><thead><tr><th>记录 UTC</th><th>事件 / 状态 / 阶段</th><th>目录 / 数量</th><th>证据</th></tr></thead><tbody><tr v-for="event in rows" :key="event.sequence"><td>{{event.recorded_at_utc}}</td><td><template v-if="event.source!=='hash'">{{kindLabels[event.kind]||event.kind}}<br></template>{{historyStatuses[event.status]||event.status}} / {{historyPhases[event.phase]||event.phase}}</td><td><template v-if="event.source==='hash'">哈希事件，见原文证据</template><template v-else>{{event.current_directory||missing}}<br>{{event.items_processed}} 项 / {{event.pages_processed}} 页</template></td><td><details><summary>展开证据</summary><p>事件序号：{{event.sequence}}</p><pre v-if="event.source==='hash'" data-testid="history-evidence-json">{{event.evidence_json||missing}}</pre><template v-else><p>工具请求：{{event.requests_used}} / {{event.request_budget==='0'?'不限':event.request_budget}}<br>待处理目录：{{event.pending_count}}<br>重核原因：{{event.restart_reason||'未记录 / 不适用'}}<br>错误：{{event.last_error||'未记录错误'}}</p><template v-if="event.source==='refresh'"><p>计划重试 UTC：{{historyTimeText(event.retry_at_utc)}}<br>云端观察 UTC：{{historyTimeText(event.cloud_observed_at_utc)}}<br>重核偏移：{{event.restart_offset??missing}}<br>重核文件 ID：{{event.restart_fs_id??missing}}<br>目录是否变化：{{event.directory_changed===null?missing:event.directory_changed?'是':'否'}}<br>新增 / 删除 / 身份变化：{{event.added_count??missing}} / {{event.removed_count??missing}} / {{event.changed_count??missing}}</p></template></template></details></td></tr><tr v-if="!loading&&!error&&!rows.length"><td colspan="4">本页没有事件，或该运行尚无可读事件记录。</td></tr></tbody></table></div><div class="path-impact-pagination"><button class="button secondary" :disabled="disabled||loading||!!error||before==='0'" @click="emit('previous')">{{previousLabel}}</button><button class="button secondary" :disabled="disabled||loading||!!error||!more" @click="emit('next',next)">更早事件</button></div><p v-if="observed" class="muted">事件本机读取 UTC：{{observed}}</p><p class="muted">所有时间均按原始 UTC 展示；展开的 JSON 是服务端脱敏后的原文，不把内层整数转换为浏览器 Number。</p></section></div></template>
<style scoped>.history-detail-drawer{width:min(880px,100vw)}.history-detail-drawer .muted,.history-detail-drawer p{overflow-wrap:anywhere}.history-detail-drawer pre{white-space:pre-wrap;overflow-wrap:anywhere;max-width:100%;font-size:12px}.history-detail-drawer h3{margin-top:24px}</style>
